# Classic public-domain prayers. Text copied from the source page named with each one (checked Oct 2026).
H62 = "https://www.eskimo.com/~lhowell/bcp1662/"
J28 = "https://justus.anglican.org/resources/bcp/1928/"
def src(name, url): return {"name": name, "url": url}
CLASSIC = [
 {"id":"c-peace","title":"A Collect for Peace","topics":["peace","afraid","protection"],
  "source":src("Book of Common Prayer (1662), Morning Prayer, the second Collect, for Peace", H62+"daily/morning.html"),
  "text":"O God, who art the author of peace and lover of concord, in knowledge of whom standeth our eternal life, whose service is perfect freedom; Defend us thy humble servants in all assaults of our enemies; that we, surely trusting in thy defence, may not fear the power of any adversaries, through the might of Jesus Christ our Lord. Amen."},
 {"id":"c-grace","title":"A Collect for Grace (morning)","topics":["morning","protection"],
  "source":src("Book of Common Prayer (1662), Morning Prayer, the third Collect, for Grace", H62+"daily/morning.html"),
  "text":"O Lord, our heavenly Father, Almighty and everlasting God, who hast safely brought us to the beginning of this day; Defend us in the same with thy mighty power; and grant that this day we fall into no sin, neither run into any kind of danger; but that all our doings may be ordered by thy governance, to do always that is righteous in thy sight; through Jesus Christ our Lord. Amen."},
 {"id":"c-lighten","title":"Lighten our darkness","topics":["night","protection","afraid"],
  "source":src("Book of Common Prayer (1662), Evening Prayer, the third Collect, for Aid against all Perils", H62+"daily/evening.html"),
  "text":"Lighten our darkness, we beseech thee, O Lord; and by thy great mercy defend us from all perils and dangers of this night; for the love of thy only Son, our Saviour, Jesus Christ. Amen."},
 {"id":"c-evening-peace","title":"That peace which the world cannot give","topics":["night","peace","anxious"],
  "source":src("Book of Common Prayer (1662), Evening Prayer, the second Collect", H62+"daily/evening.html"),
  "text":"O God, from whom all holy desires, all good counsels, and all just works do proceed; Give unto thy servants that peace which the world cannot give; that both our hearts may be set to obey thy commandments, and also that by thee, we, being defended from the fear of our enemies, may pass our time in rest and quietness; through the merits of Jesus Christ our Saviour. Amen."},
 {"id":"c-thanksgiving","title":"A General Thanksgiving","topics":["thankful","joyful"],
  "source":src("Book of Common Prayer (1662), A General Thanksgiving (the optional bracketed clause is left out)", H62+"daily/thanksgivings.html"),
  "text":"Almighty God, Father of all mercies, we thine unworthy servants do give thee most humble and hearty thanks for all thy goodness and loving-kindness to us, and to all men. We bless thee for our creation, preservation, and all the blessings of this life; but above all, for thine inestimable love in the redemption of the world by our Lord Jesus Christ; for the means of grace, and for the hope of glory. And, we beseech thee, give us that due sense of all thy mercies, that our hearts may be unfeignedly thankful, and that we shew forth thy praise, not only with our lips, but in our lives; by giving up ourselves to thy service, and by walking before thee in holiness and righteousness all our days; through Jesus Christ our Lord, to whom with thee and the Holy Ghost be all honour and glory, world without end. Amen."},
 {"id":"c-scriptures","title":"Read, mark, learn, and inwardly digest","topics":["study","focus"],
  "source":src("Book of Common Prayer (1662), Collect for the Second Sunday in Advent", H62+"communion/xmas.html"),
  "text":"Blessed Lord, who hast caused all holy Scriptures to be written for our learning; Grant that we may in such wise hear them, read, mark, learn, and inwardly digest them, that by patience and comfort of thy holy Word, we may embrace, and ever hold fast, the blessed hope of everlasting life, which thou hast given us in our Saviour Jesus Christ. Amen."},
 {"id":"c-purity","title":"The Collect for Purity","topics":["guilty","peace"],
  "source":src("Book of Common Prayer (1662), The Communion, Collect for Purity", H62+"communion/index.html"),
  "text":"Almighty God, unto whom all hearts be open, all desires known, and from whom no secrets are hid; Cleanse the thoughts of our hearts by the inspiration of thy Holy Spirit, that we may perfectly love thee, and worthily magnify thy holy Name; through Christ our Lord. Amen."},
 {"id":"c-protector","title":"The protector of all that trust in thee","topics":["strength","protection","guidance"],
  "source":src("Book of Common Prayer (1662), Collect for the Fourth Sunday after Trinity", H62+"communion/trinity.html"),
  "text":"O God, the protector of all that trust in thee, without whom nothing is strong, nothing is holy; Increase and multiply upon us thy mercy; that, thou being our ruler and guide, we may so pass through things temporal, that we finally lose not the things eternal: Grant this, O heavenly Father, for Jesus Christ's sake our Lord. Amen."},
 {"id":"c-prevent","title":"In all our works begun, continued, and ended","topics":["work","business","study","testday"],
  "source":src("Book of Common Prayer (1662), The Communion, closing collects (“Prevent” here means “go before”)", H62+"communion/index.html"),
  "text":"Prevent us O Lord, in all our doings with thy most gracious favour, and further us with thy continual help; that in all our works begun, continued, and ended in thee, we may glorify thy holy Name, and finally by thy mercy obtain everlasting life; through Jesus Christ our Lord. Amen."},
 {"id":"c-pardon","title":"Pardon and peace","topics":["forgiveness","guilty","peace","anxious"],
  "source":src("Book of Common Prayer (1662), Collect for the Twenty-first Sunday after Trinity", H62+"communion/trinity.html"),
  "text":"Grant, we beseech thee, merciful Lord, to thy faithful people pardon and peace, that they may be cleansed from all their sins, and serve thee with a quiet mind; through Jesus Christ our Lord. Amen."},
 {"id":"c-quiet","title":"For Quiet Confidence","topics":["anxious","peace","weary"],
  "source":src("Book of Common Prayer (1928, US), Family Prayer, For Quiet Confidence", J28+"Family_Prayer.htm"),
  "text":"O God of peace, who hast taught us that in returning and rest we shall be saved, in quietness and in confidence shall be our strength; By the might of thy Spirit lift us, we pray thee, to thy presence, where we may be still and know that thou art God; through Jesus Christ our Lord. Amen."},
 {"id":"c-keepwatch","title":"Keep watch, dear Lord","topics":["night","healing","weary","sad","family"],
  "source":src("Book of Common Prayer (1979, US), Evening Prayer: Rite One", "https://www.bcponline.org/DailyOffice/ep1.html"),
  "text":"Keep watch, dear Lord, with those who work, or watch, or weep this night, and give thine angels charge over those who sleep. Tend the sick, Lord Christ; give rest to the weary, bless the dying, soothe the suffering, pity the afflicted, shield the joyous; and all for thy love's sake. Amen."},
 {"id":"c-sick","title":"For the Recovery of a Sick Person","topics":["healing","family"],
  "source":src("Book of Common Prayer (1928, US), Family Prayer, For the Recovery of a Sick Person (say the person's name at N.)", J28+"Family_Prayer.htm"),
  "text":"O merciful God, giver of life and health; Bless, we pray thee, thy servant, N., and those who administer to him of thy healing gifts; that he may be restored to health of body and of mind; through Jesus Christ our Lord. Amen."},
 {"id":"c-loved","title":"For Those We Love","topics":["family","protection","sad"],
  "source":src("Book of Common Prayer (1928, US), Family Prayer, For Those We Love", J28+"Family_Prayer.htm"),
  "text":"Almighty God, we entrust all who are dear to us to thy never-failing care and love, for this life and the life to come; knowing that thou art doing for them better things than we can desire or pray for; through Jesus Christ our Lord. Amen."},
 {"id":"c-mourn","title":"For all those who mourn","topics":["sad","lonely"],
  "source":src("Book of Common Prayer (1928, US), The Burial of the Dead", J28+"Burial.htm"),
  "text":"Almighty God, Father of mercies and giver of all comfort; Deal graciously, we pray thee, with all those who mourn, that, casting every care on thee, they may know the consolation of thy love; through Jesus Christ our Lord. Amen."},
 {"id":"c-guidance","title":"For Guidance","topics":["guidance","wisdom","business","waiting"],
  "source":src("Book of Common Prayer (1928, US), Family Prayer, For Guidance", J28+"Family_Prayer.htm"),
  "text":"O God, by whom the meek are guided in judgment, and light riseth up in darkness for the godly; Grant us, in all our doubts and uncertainties, the grace to ask what thou wouldest have us to do, that the Spirit of Wisdom may save us from all false choices, and that in thy light we may see light, and in thy straight path may not stumble; through Jesus Christ our Lord. Amen."},
 {"id":"c-affliction","title":"For a Person under Affliction","topics":["sad","discouraged","healing"],
  "source":src("Book of Common Prayer (1928, US), Prayers and Thanksgivings, For a Person under Affliction", J28+"Pray&Thanks.htm"),
  "text":"O merciful God, and heavenly Father, who hast taught us in thy holy Word that thou dost not willingly afflict or grieve the children of men; Look with pity, we beseech thee, upon the sorrows of thy servant for whom our prayers are offered. Remember him, O Lord, in mercy; endue his soul with patience; comfort him with a sense of thy goodness; lift up thy countenance upon him, and give him peace; through Jesus Christ our Lord. Amen."},
 {"id":"c-work","title":"For Every Man in his Work","topics":["work","business","money"],
  "source":src("Book of Common Prayer (1928, US), Prayers and Thanksgivings, For Every Man in his Work", J28+"Pray&Thanks.htm"),
  "text":"Almighty God, our heavenly Father, who declarest thy glory and showest forth thy handiwork in the heavens and in the earth; Deliver us, we beseech thee, in our several callings, from the service of mammon, that we may do the work which thou givest us to do, in truth, in beauty, and in righteousness, with singleness of heart as thy servants, and to the benefit of our fellow men; for the sake of him who came among us as one that serveth, thy Son, Jesus Christ our Lord. Amen."},
 {"id":"c-richard","title":"Day by day (St. Richard of Chichester)","topics":["joyful","thankful","morning"],
  "source":src("Prayer of St. Richard of Chichester (1197–1253), Devout.org prayer book", "https://www.devout.org/prayer-book/prayer-of-st-richard"),
  "text":"Thanks be to thee, my Lord Jesus Christ,\nfor all the benefits thou hast given me,\nfor all the pains and insults thou hast borne for me.\nO most merciful Redeemer, friend and brother,\nmay I know thee more clearly,\nlove thee more dearly,\nand follow thee more nearly, day by day. Amen."},
 {"id":"c-teresa","title":"Let nothing disturb thee (St. Teresa of Avila)","topics":["anxious","afraid","peace","waiting"],
  "source":src("Teresa of Avila, translated by Henry Wadsworth Longfellow; text as printed in Thomas Walsh, ed., Hispanic Anthology (1920)", "https://www4.gvsu.edu/wrightd/Honors%20216/LetNothingDisturbThee.htm"),
  "text":"Let nothing disturb thee,\nNothing affright thee\nAll things are passing;\nGod never changeth;\nPatient endurance\nAttaineth to all things;\nWho God possesseth\nIn nothing is wanting;\nAlone God sufficeth."},
 {"id":"c-patrick","title":"Christ be with me (St. Patrick's Breastplate)","topics":["protection","afraid","lonely","morning"],
  "source":src("St. Patrick's Breastplate, translated by Cecil Frances Alexander (1889), public domain (Hymnary.org)", "https://hymnary.org/text/i_bind_unto_myself_today"),
  "text":"Christ be with me, Christ within me,\nChrist behind me, Christ before me,\nChrist beside me, Christ to win me,\nChrist to comfort and restore me.\nChrist beneath me, Christ above me,\nChrist in quiet, Christ in danger,\nChrist in hearts of all that love me,\nChrist in mouth of friend and stranger."},
 {"id":"c-francis","title":"Make me an instrument of thy peace","topics":["peace","angry","forgiveness","family"],
  "source":src("The Peace Prayer, traditionally attributed to St. Francis. First printed in French in 1912 (La Clochette); first in English in 1927 (Friends' Intelligencer). This traditional English form as given by Marquette University", "https://www.marquette.edu/faith/prayer-peace.php"),
  "text":"Lord, make me an instrument of thy peace;\nwhere there is hatred, let me sow love;\nwhere there is injury, pardon;\nwhere there is discord, union;\nwhere there is doubt, faith;\nwhere there is despair, hope;\nwhere there is darkness, light;\nand where there is sadness, joy.\nO Divine Master, grant that I may not so much seek\nto be consoled as to console,\nto be understood, as to understand;\nto be loved, as to love;\nfor it is in giving that we receive,\nit is in pardoning that we are pardoned,\nand it is in dying that we are born\nto eternal life."},
 {"id":"c-augustine","title":"Our heart is restless (St. Augustine)","topics":["lonely","anxious","discouraged"],
  "source":src("St. Augustine, Confessions, Book I, translated by E. B. Pusey (Project Gutenberg #3296)", "https://www.gutenberg.org/cache/epub/3296/pg3296.txt"),
  "text":"Thou awakest us to delight in Thy praise; for Thou madest us for Thyself, and our heart is restless, until it repose in Thee."},
]
